import sys

def thanos_sort_max_length(arr):
    def is_sorted(subarr):
        return all(subarr[i] <= subarr[i + 1] for i in range(len(subarr) - 1))

    def max_sorted_length(arr, start, end):
        if start >= end:
            return 0

        mid = (start + end) // 2
        left_sorted_length = max_sorted_length(arr, start, mid)
        right_sorted_length = max_sorted_length(arr, mid, end)

        if is_sorted(arr[start:end]):
            return end - start

        return max(left_sorted_length, right_sorted_length)

    return max_sorted_length(arr, 0, len(arr))

if __name__ == "__main__":
    n = int(sys.stdin.readline().strip())
    arr = list(map(int, sys.stdin.readline().strip().split()))
    print(thanos_sort_max_length(arr))
